[{"order":1,"type":"heading","text":"RESTful API Integration, HttpClient, and Refit in Xamarin"},{"order":2,"type":"paragraph","text":"Integrating RESTful APIs is a fundamental requirement for modern mobile applications. In Xamarin.Forms or Xamarin.Android/iOS, developers have traditionally relied on standard .NET HTTP client utilities. However, modern approaches like Refit offer a type-safe, declarative REST library that drastically reduces boilerplate code."},{"order":3,"type":"subheading","text":"Method 1: Standard HttpClient Approach"},{"order":4,"type":"paragraph","text":"The traditional way to consume REST APIs in .NET utilizes the HttpClient class along with Newtonsoft.Json or System.Text.Json for serialization. While flexible, it requires manual URI construction and status code handling."},{"order":5,"type":"code","text":"using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class ApiService
{
    private readonly HttpClient _client;

    public ApiService()
    {
        _client = new HttpClient
        {
            BaseAddress = new Uri("https://jsonplaceholder.typicode.com/")
        };
    }

    public async Task<User> GetUserAsync(int id)
    {
        var response = await _client.GetAsync($"users/{id}");
        if (response.IsSuccessStatusCode)
        {
            var content = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<User>(content);
        }
        return null;
    }
}"},{"order":6,"type":"subheading","text":"Method 2: The Refit Approach (Declarative REST)"},{"order":7,"type":"paragraph","text":"Refit turns your REST API into a live interface. By defining a C# interface with specific attributes, Refit automatically generates the underlying implementation, keeping your codebase clean and testable."},{"order":8,"type":"code","text":"using System.Threading.Tasks;
using Refit;

public interface IUserService
{
    [Get("/users/{id}")]
    Task<User> GetUserAsync(int id);

    [Post("/users")]
    Task<User> CreateUserAsync([Body] User user);
}"},{"order":9,"type":"subheading","text":"Configuring and Consuming Refit in Xamarin"},{"order":10,"type":"paragraph","text":"To use Refit in your Xamarin application, initialize it using RestService.For with your base URL. It internally leverages HttpClient, so you can easily configure delegating handlers for authentication headers."},{"order":11,"type":"code","text":"using Refit;

public class UserServiceManager
{
    public async Task FetchAndDisplayUser(int userId)
    {
        var userService = RestService.For<IUserService>("https://jsonplaceholder.typicode.com");

        try
        {
            var user = await userService.GetUserAsync(userId);
            System.Diagnostics.Debug.WriteLine($"Loaded User: {user.Name}");
        }
        catch (ApiException ex)
        {
            System.Diagnostics.Debug.WriteLine($"API Error: {ex.Message}");
        }
    }
}"},{"order":12,"type":"subheading","text":"Best Practices for Xamarin API Integration"},{"order":13,"type":"bullet_point","text":"Singleton HttpClient: Avoid instantiating new HttpClient instances per request to prevent socket exhaustion."},{"order":14,"type":"bullet_point","text":"Error Handling: Always wrap API calls in try-catch blocks, handling Refit's ApiException or standard HttpRequestException gracefully."},{"order":15,"type":"bullet_point","text":"Dependency Injection: Register Refit interfaces with your DI container (like Microsoft.Extensions.DependencyInjection or Autofac) for cleaner architecture."}]
